fn test_ruby_description_is_defined() {
    crate::on_ruby_thread(|| {
        let eval = |code: &str| {
            VM::eval(code)
                .unwrap()
                .try_convert_to::<RString>()
                .unwrap()
                .to_string()
        };
        let built =
